from pathlib import Path

vm_path = Path('app/src/main/java/com/example/ui/ReceiptViewModel.kt')
ui_path = Path('app/src/main/java/com/example/ui/BankFeature.kt')
vm = vm_path.read_text()
ui = ui_path.read_text()

state_anchor = '''    private val _bankImportStatus = MutableStateFlow<String?>(null)\n    val bankImportStatus: StateFlow<String?> = _bankImportStatus.asStateFlow()\n'''
state_insert = state_anchor + '''    private val _bankUndoState = MutableStateFlow<com.example.data.BankUndoState?>(null)\n    val bankUndoState: StateFlow<com.example.data.BankUndoState?> = _bankUndoState.asStateFlow()\n'''
if state_anchor not in vm:
    raise SystemExit('bank status state anchor not found')
vm = vm.replace(state_anchor, state_insert, 1)

batch_start = vm.index('    fun executeBankBatchAction(')
batch_end = vm.index('    fun markBankTransactionPrivateIgnored', batch_start)
old_batch = vm[batch_start:batch_end]
new_batch = '''    fun executeBankBatchAction(\n        transactionIds: List<String>,\n        action: com.example.data.BankBatchAction\n    ) {\n        viewModelScope.launch(Dispatchers.IO) {\n            val dao = database.bankDao()\n            val current = transactionIds.distinct().mapNotNull { dao.getTransaction(it) }\n            val preview = com.example.data.BankBatchActionPolicy.preview(current, dao.getAllLinks(), action)\n            val now = java.time.Instant.now().toString()\n            val undoEntries = mutableListOf<com.example.data.BankUndoEntry>()\n\n            preview.eligibleTransactionIds.forEach { transactionId ->\n                val transaction = dao.getTransaction(transactionId) ?: return@forEach\n                when (action) {\n                    com.example.data.BankBatchAction.PRIVATE_IGNORED,\n                    com.example.data.BankBatchAction.TRANSFER -> {\n                        val target = if (action == com.example.data.BankBatchAction.PRIVATE_IGNORED)\n                            com.example.data.BankTransactionClassification.PRIVATE_IGNORED\n                        else com.example.data.BankTransactionClassification.TRANSFER\n                        undoEntries += com.example.data.BankUndoEntry(\n                            transactionId = transaction.transactionId,\n                            fieldSet = com.example.data.BankUndoFieldSet.CLASSIFICATION,\n                            expectedUpdatedAt = now,\n                            classification = transaction.classification,\n                            transferCounterAccountId = transaction.transferCounterAccountId,\n                            linkedTransferTransactionId = transaction.linkedTransferTransactionId,\n                            reviewState = transaction.reviewState\n                        )\n                        val updated = com.example.data.BankClassificationPolicy.classify(\n                            transactionId = transaction.transactionId,\n                            classification = target,\n                            now = now\n                        )\n                        dao.updateTransactionClassification(\n                            transactionId = transaction.transactionId,\n                            classification = updated.classification,\n                            transferCounterAccountId = updated.transferCounterAccountId,\n                            linkedTransferTransactionId = updated.linkedTransferTransactionId,\n                            reviewState = updated.reviewState,\n                            updatedAt = now\n                        )\n                    }\n                    com.example.data.BankBatchAction.NO_RECEIPT_REQUIRED -> {\n                        undoEntries += com.example.data.BankUndoEntry(\n                            transactionId = transaction.transactionId,\n                            fieldSet = com.example.data.BankUndoFieldSet.RECONCILIATION,\n                            expectedUpdatedAt = now,\n                            reconciliationStatus = transaction.reconciliationStatus,\n                            noReceiptReason = transaction.noReceiptReason\n                        )\n                        dao.updateTransactionStatus(\n                            transaction.transactionId,\n                            com.example.data.BankReconciliationStatus.NO_RECEIPT_REQUIRED,\n                            "Sammelaktion: Beleg nicht erforderlich",\n                            now\n                        )\n                    }\n                }\n            }\n\n            if (undoEntries.isNotEmpty()) {\n                val label = when (action) {\n                    com.example.data.BankBatchAction.PRIVATE_IGNORED -> "Privat-Sammelaktion"\n                    com.example.data.BankBatchAction.TRANSFER -> "Umbuchungs-Sammelaktion"\n                    com.example.data.BankBatchAction.NO_RECEIPT_REQUIRED -> "Kein-Beleg-Sammelaktion"\n                }\n                _bankUndoState.value = com.example.data.BankUndoState(label, undoEntries)\n            }\n            _bankImportStatus.value = buildString {\n                append("Sammelaktion abgeschlossen: ${preview.eligibleCount} geändert")\n                if (preview.unchangedCount > 0) append(" • ${preview.unchangedCount} bereits passend")\n                if (preview.conflictCount > 0) append(" • ${preview.conflictCount} aus Sicherheitsgründen übersprungen")\n                append(".")\n            }\n        }\n    }\n\n    fun undoLastBankAction() {\n        viewModelScope.launch(Dispatchers.IO) {\n            val state = _bankUndoState.value ?: return@launch\n            val dao = database.bankDao()\n            val current = state.entries.mapNotNull { dao.getTransaction(it.transactionId) }\n            val decision = com.example.data.BankUndoPolicy.decide(current, state)\n            val now = java.time.Instant.now().toString()\n            decision.restorable.forEach { entry ->\n                when (entry.fieldSet) {\n                    com.example.data.BankUndoFieldSet.CLASSIFICATION -> dao.updateTransactionClassification(\n                        transactionId = entry.transactionId,\n                        classification = entry.classification,\n                        transferCounterAccountId = entry.transferCounterAccountId,\n                        linkedTransferTransactionId = entry.linkedTransferTransactionId,\n                        reviewState = entry.reviewState,\n                        updatedAt = now\n                    )\n                    com.example.data.BankUndoFieldSet.RECONCILIATION -> dao.updateTransactionStatus(\n                        transactionId = entry.transactionId,\n                        status = entry.reconciliationStatus,\n                        reason = entry.noReceiptReason,\n                        updatedAt = now\n                    )\n                }\n            }\n            _bankUndoState.value = null\n            _bankImportStatus.value = buildString {\n                append("Rückgängig: ${decision.restorable.size} Buchung(en) wiederhergestellt")\n                if (decision.skipped.isNotEmpty()) append(" • ${decision.skipped.size} wegen neuerer Änderungen übersprungen")\n                append(".")\n            }\n        }\n    }\n\n    fun dismissBankUndo() {\n        _bankUndoState.value = null\n    }\n\n'''
vm = vm[:batch_start] + new_batch + vm[batch_end:]

class_anchor = '''            val transaction = dao.getTransaction(transactionId) ?: return@launch\n            val now = java.time.Instant.now().toString()\n'''
class_insert = '''            val transaction = dao.getTransaction(transactionId) ?: return@launch\n            val canOfferUndo = transaction.linkedTransferTransactionId.isBlank()\n            val now = java.time.Instant.now().toString()\n'''
if class_anchor not in vm:
    raise SystemExit('classification transaction anchor not found')
vm = vm.replace(class_anchor, class_insert, 1)

class_update_anchor = '''            dao.updateTransactionClassification(\n                transactionId = transactionId,\n                classification = updated.classification,\n                transferCounterAccountId = updated.transferCounterAccountId,\n                linkedTransferTransactionId = updated.linkedTransferTransactionId,\n                reviewState = updated.reviewState,\n                updatedAt = now\n            )\n            _bankImportStatus.value = when (updated.classification) {\n'''
class_update_insert = '''            dao.updateTransactionClassification(\n                transactionId = transactionId,\n                classification = updated.classification,\n                transferCounterAccountId = updated.transferCounterAccountId,\n                linkedTransferTransactionId = updated.linkedTransferTransactionId,\n                reviewState = updated.reviewState,\n                updatedAt = now\n            )\n            if (canOfferUndo) {\n                _bankUndoState.value = com.example.data.BankUndoState(\n                    label = "Buchungsklassifikation",\n                    entries = listOf(com.example.data.BankUndoEntry(\n                        transactionId = transaction.transactionId,\n                        fieldSet = com.example.data.BankUndoFieldSet.CLASSIFICATION,\n                        expectedUpdatedAt = now,\n                        classification = transaction.classification,\n                        transferCounterAccountId = transaction.transferCounterAccountId,\n                        linkedTransferTransactionId = transaction.linkedTransferTransactionId,\n                        reviewState = transaction.reviewState\n                    ))\n                )\n            } else {\n                _bankUndoState.value = null\n            }\n            _bankImportStatus.value = when (updated.classification) {\n'''
if class_update_anchor not in vm:
    raise SystemExit('classification update anchor not found')
vm = vm.replace(class_update_anchor, class_update_insert, 1)

no_receipt_anchor = '''    fun markBankTransactionNoReceiptRequired(transactionId: String, reason: String) {\n        viewModelScope.launch(Dispatchers.IO) {\n            val dao = database.bankDao()\n            if (dao.getLinksForTransaction(transactionId).isNotEmpty()) {\n'''
no_receipt_insert = '''    fun markBankTransactionNoReceiptRequired(transactionId: String, reason: String) {\n        viewModelScope.launch(Dispatchers.IO) {\n            val dao = database.bankDao()\n            val transaction = dao.getTransaction(transactionId) ?: return@launch\n            if (dao.getLinksForTransaction(transactionId).isNotEmpty()) {\n'''
if no_receipt_anchor not in vm:
    raise SystemExit('no receipt start anchor not found')
vm = vm.replace(no_receipt_anchor, no_receipt_insert, 1)

no_receipt_update = '''            dao.updateTransactionStatus(\n                transactionId,\n                com.example.data.BankReconciliationStatus.NO_RECEIPT_REQUIRED,\n                reason.trim(),\n                java.time.Instant.now().toString()\n            )\n            _bankImportStatus.value = "Als „kein Beleg erforderlich“ markiert: ${reason.trim()}."\n'''
no_receipt_repl = '''            val now = java.time.Instant.now().toString()\n            dao.updateTransactionStatus(\n                transactionId,\n                com.example.data.BankReconciliationStatus.NO_RECEIPT_REQUIRED,\n                reason.trim(),\n                now\n            )\n            _bankUndoState.value = com.example.data.BankUndoState(\n                label = "Kein Beleg erforderlich",\n                entries = listOf(com.example.data.BankUndoEntry(\n                    transactionId = transaction.transactionId,\n                    fieldSet = com.example.data.BankUndoFieldSet.RECONCILIATION,\n                    expectedUpdatedAt = now,\n                    reconciliationStatus = transaction.reconciliationStatus,\n                    noReceiptReason = transaction.noReceiptReason\n                ))\n            )\n            _bankImportStatus.value = "Als „kein Beleg erforderlich“ markiert: ${reason.trim()}."\n'''
if no_receipt_update not in vm:
    raise SystemExit('no receipt update anchor not found')
vm = vm.replace(no_receipt_update, no_receipt_repl, 1)

collect_anchor = '''    val importStatus by viewModel.bankImportStatus.collectAsState()\n    val learningRules by viewModel.bankLearningRules.collectAsState()\n'''
collect_insert = '''    val importStatus by viewModel.bankImportStatus.collectAsState()\n    val undoState by viewModel.bankUndoState.collectAsState()\n    val learningRules by viewModel.bankLearningRules.collectAsState()\n'''
if collect_anchor not in ui:
    raise SystemExit('undo collect anchor not found')
ui = ui.replace(collect_anchor, collect_insert, 1)

call_anchor = '''            units = units,\n            onBack = { selectedTransactionId = null },\n'''
call_insert = '''            units = units,\n            undoState = undoState,\n            onUndo = { viewModel.undoLastBankAction() },\n            onDismissUndo = { viewModel.dismissBankUndo() },\n            onBack = { selectedTransactionId = null },\n'''
if call_anchor not in ui:
    raise SystemExit('detail call anchor not found')
ui = ui.replace(call_anchor, call_insert, 1)

list_anchor = '''            item {\n                Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()), horizontalArrangement = Arrangement.spacedBy(6.dp)) {\n'''
undo_card = '''            if (undoState != null) {\n                item {\n                    BankUndoBanner(undoState!!, onUndo = { viewModel.undoLastBankAction() }, onDismiss = { viewModel.dismissBankUndo() })\n                }\n            }\n\n''' + list_anchor
if list_anchor not in ui:
    raise SystemExit('list undo anchor not found')
ui = ui.replace(list_anchor, undo_card, 1)

detail_sig_anchor = '''    rentSuggestion: com.example.data.BankRentSuggestion?,\n    units: List<WohneinheitStatus>,\n    onBack: () -> Unit,\n'''
detail_sig_insert = '''    rentSuggestion: com.example.data.BankRentSuggestion?,\n    units: List<WohneinheitStatus>,\n    undoState: com.example.data.BankUndoState?,\n    onUndo: () -> Unit,\n    onDismissUndo: () -> Unit,\n    onBack: () -> Unit,\n'''
if detail_sig_anchor not in ui:
    raise SystemExit('detail signature anchor not found')
ui = ui.replace(detail_sig_anchor, detail_sig_insert, 1)

detail_header_anchor = '''        item {\n            Card(colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface), border = BorderStroke(1.dp, BorderColor)) {\n'''
detail_undo = '''        if (undoState != null) {\n            item { BankUndoBanner(undoState, onUndo = onUndo, onDismiss = onDismissUndo) }\n        }\n        item {\n            Card(colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface), border = BorderStroke(1.dp, BorderColor)) {\n'''
# Replace only the first details-card occurrence after function declaration.
detail_pos = ui.index('private fun BankTransactionDetailsScreen(')
anchor_pos = ui.index(detail_header_anchor, detail_pos)
ui = ui[:anchor_pos] + ui[anchor_pos:].replace(detail_header_anchor, detail_undo, 1)

banner_anchor = '''private data class BankTransactionVisual(\n'''
banner = '''@Composable\nprivate fun BankUndoBanner(\n    state: com.example.data.BankUndoState,\n    onUndo: () -> Unit,\n    onDismiss: () -> Unit\n) {\n    Card(\n        modifier = Modifier.fillMaxWidth(),\n        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),\n        border = BorderStroke(1.dp, BorderColor)\n    ) {\n        Row(Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically) {\n            Column(Modifier.weight(1f)) {\n                Text("${state.label} ausgeführt", fontWeight = FontWeight.SemiBold, color = DarkNavy, fontSize = 12.sp)\n                Text("${state.entries.size} Änderung(en) können sicher rückgängig gemacht werden.", fontSize = 10.sp, color = SlateGray)\n            }\n            TextButton(onClick = onUndo) { Text("Rückgängig") }\n            TextButton(onClick = onDismiss) { Text("Schließen") }\n        }\n    }\n}\n\n''' + banner_anchor
if banner_anchor not in ui:
    raise SystemExit('banner anchor not found')
ui = ui.replace(banner_anchor, banner, 1)

vm_path.write_text(vm)
ui_path.write_text(ui)
